validate:
// Minimum Wages Order 2024: a monthly-rated employee earns at least RM1,700 a month.
const rate = get(ctx.entry, 'terms.rate', null);
if (rate == null || get(rate, 'unit', null) !== 'MONTHLY') return true;
if (['PART_TIME', 'APPRENTICE', 'PAYEE'].includes(get(ctx.entry, 'engagement', 'EMPLOYEE'))) return true;
if (get(ctx.entry, 'terms.statutory_work_category', null) === 'TASK_BASIS') return true;
const facts = get(ctx.entry, 'employee_extension_data.term_facts', {});
if (get(facts, 'industrial_training_student', false) === true) return true;
return get(rate, 'amount', 0) >= ctx.lookup.monthly_wage;

// A part-time rate is reduced to its hourly equivalent and held to the hourly floor.
const rate = get(ctx.entry, 'terms.rate', null);
if (get(ctx.entry, 'engagement', 'EMPLOYEE') !== 'PART_TIME' || rate == null) return true;
const facts = get(ctx.entry, 'employee_extension_data.term_facts', {});
if (get(facts, 'industrial_training_student', false) === true) return true;
const unit = get(rate, 'unit', null);
const amount = get(rate, 'amount', 0);
const week = Number(get(ctx.entry, 'terms.normal_hours_per_week', 0));
const day = Number(get(ctx.entry, 'terms.normal_hours_per_day', 0));
const hourly =
  unit === 'MONTHLY' && week > 0 ? (amount * ctx.lookup.months_per_year) / (ctx.lookup.weeks_per_year * week)
  : unit === 'WEEKLY' && week > 0 ? amount / week
  : unit === 'DAILY' && day > 0 ? amount / day
  : unit === 'HOURLY' ? amount
  : null;
return hourly == null || hourly >= ctx.lookup.hourly_wage;

// A Sabah or Sarawak worksite belongs to a Labour Ordinance lineage, not the Employment Act.
const facts = get(ctx.entry, 'employee_extension_data.term_facts', {});
const region = get(ctx.entry, 'terms.work_region', get(facts, 'work_region', get(facts, 'worksite_state', null)));
return region == null || !ctx.lookup.excluded.includes(region);

// EA s.60A(1)(d): normal hours are at most 45 a week; shift work averages over three weeks.
const hours = get(ctx.entry, 'terms.normal_hours_per_week', null);
if (hours == null) return true;
const facts = get(ctx.entry, 'employee_extension_data.term_facts', {});
if (get(facts, 'shift_work', false) === true) return true;
return hours <= ctx.lookup.normal_hours_per_week;

// The daily floor follows the agreed number of working days a week.
const rate = get(ctx.entry, 'terms.rate', null);
if (rate == null || get(rate, 'unit', null) !== 'DAILY') return true;
if (['APPRENTICE', 'PAYEE'].includes(get(ctx.entry, 'engagement', 'EMPLOYEE'))) return true;
const facts = get(ctx.entry, 'employee_extension_data.term_facts', {});
if (get(facts, 'industrial_training_student', false) === true) return true;
const days = Number(get(ctx.entry, 'terms.normal_days_per_week', 6));
const floor =
  days <= 4 ? ctx.lookup.daily_four_day_week
  : days === 5 ? ctx.lookup.daily_five_day_week
  : ctx.lookup.daily_six_day_week;
return get(rate, 'amount', 0) >= floor;

// A weekly rate is at least the daily floor times the agreed working days a week.
const rate = get(ctx.entry, 'terms.rate', null);
if (rate == null || get(rate, 'unit', null) !== 'WEEKLY') return true;
if (['APPRENTICE', 'PAYEE', 'PART_TIME'].includes(get(ctx.entry, 'engagement', 'EMPLOYEE'))) return true;
const facts = get(ctx.entry, 'employee_extension_data.term_facts', {});
if (get(facts, 'industrial_training_student', false) === true) return true;
const days = Number(get(ctx.entry, 'terms.normal_days_per_week', 6));
const floor =
  days <= 4 ? ctx.lookup.daily_four_day_week
  : days === 5 ? ctx.lookup.daily_five_day_week
  : ctx.lookup.daily_six_day_week;
return get(rate, 'amount', 0) >= floor * days;

// An hourly rate is at least RM8.72.
const rate = get(ctx.entry, 'terms.rate', null);
if (rate == null || get(rate, 'unit', null) !== 'HOURLY') return true;
if (['APPRENTICE', 'PAYEE'].includes(get(ctx.entry, 'engagement', 'EMPLOYEE'))) return true;
const facts = get(ctx.entry, 'employee_extension_data.term_facts', {});
if (get(facts, 'industrial_training_student', false) === true) return true;
return get(rate, 'amount', 0) >= ctx.lookup.hourly_wage;

// EA s.25A: wages go through the employee's bank account; another method needs the written request and, for cash or cheque, the Director General's approval.
const method = get(ctx.entry, 'terms.wage_payment_method', null);
if (method == null || ctx.lookup.bank_methods.includes(method)) return true;
const facts = get(ctx.entry, 'employee_extension_data.term_facts', {});
const approval = get(facts, ctx.lookup.approval_fact, '');
return typeof approval === 'string' && approval !== '';

// EA s.18: the employer's payment schedule may not span more than one month.
const schedule = get(ctx.entry, 'payment_schedule', null);
if (schedule == null || get(schedule, 'frequency', null) !== 'INTEGER_MONTHS') return true;
return Number(get(schedule, 'month_interval', 1)) <= ctx.lookup.maximum_months;

// EA s.60A(1)(a): planned overtime beyond five continuous hours needs a thirty-minute break.
const planned = get(ctx.entry, 'planned_overtime_intervals', []);
if (planned.length !== 1) return true;
const breaks = interval_minutes(flatten(planned.map((i) => get(i, 'breaks', []))));
return !(interval_minutes(planned) > ctx.lookup.elapsed_minutes && breaks < ctx.lookup.break_minutes);

// EA s.60A(7): planned overtime may not push the day past twelve hours.
const limit = ctx.lookup.minutes_per_day - ctx.lookup.normal_minutes_per_day;
return interval_minutes(get(ctx.entry, 'planned_overtime_intervals', [])) <= limit;

// Act 350 s.2(2): a child under fifteen needs a permitted employment category.
const born = get(ctx.entry, 'payroll.date_of_birth', null);
const from = get(ctx.entry, 'effective_range.from', null);
if (born == null || from == null) return true;
if (age_on(born, from) >= ctx.lookup.maximum_age) return true;
const facts = get(ctx.entry, 'employee_extension_data.term_facts', {});
return ctx.lookup.permitted_kinds.includes(get(facts, 'minor_employment_kind', null));

// Act 350 s.2(2A): light family work requires age thirteen or above.
const born = get(ctx.entry, 'payroll.date_of_birth', null);
const from = get(ctx.entry, 'effective_range.from', null);
if (born == null || from == null) return true;
const facts = get(ctx.entry, 'employee_extension_data.term_facts', {});
if (get(facts, 'minor_employment_kind', null) !== ctx.lookup.kind) return true;
return age_on(born, from) >= ctx.lookup.minimum_age;

// Act 350 s.2(1A)-(1B): hazardous work is closed to children and supervised for young persons.
const born = get(ctx.entry, 'payroll.date_of_birth', null);
const from = get(ctx.entry, 'effective_range.from', null);
if (born == null || from == null) return true;
const age = age_on(born, from);
if (age >= ctx.lookup.maximum_age) return true;
const facts = get(ctx.entry, 'employee_extension_data.term_facts', {});
if (get(facts, 'hazardous_work', false) !== true) return true;
if (age < ctx.lookup.child_age) return false;
return get(facts, 'hazardous_work_personal_supervision', false) === true && get(facts, 'hazardous_work_training', false) === true;

// Act 350 s.2(2B): Fifth Schedule employment is closed to every person under eighteen.
const born = get(ctx.entry, 'payroll.date_of_birth', null);
const from = get(ctx.entry, 'effective_range.from', null);
if (born == null || from == null) return true;
if (age_on(born, from) >= ctx.lookup.maximum_age) return true;
const facts = get(ctx.entry, 'employee_extension_data.term_facts', {});
return get(facts, 'prohibited_minor_employment', false) !== true;

// The jurisdiction admits only these contract categories.
const categories = ctx.lookup.categories;
const category = get(ctx.entry, 'terms.statutory_work_category', null);
if (category != null && !categories.statutory_work_category.includes(category)) return false;
const residency = get(ctx.entry, 'terms.residency_status', null);
if (residency != null && !categories.residency_status.includes(residency)) return false;
return true;

// The agreed rate and normal working time must meet this version's contract limits.
const limits = ctx.lookup.limits;
const rate = get(ctx.entry, 'terms.rate', null);
if (rate != null && get(rate, 'amount', 0) < 0) return false;
const day = get(ctx.entry, 'terms.normal_hours_per_day', null);
if (day != null && !(day > 0 && day <= limits.normal_hours_per_day_maximum)) return false;
const week = get(ctx.entry, 'terms.normal_hours_per_week', null);
if (week != null && week < limits.normal_hours_per_week_minimum) return false;
const days = get(ctx.entry, 'terms.normal_days_per_week', null);
if (days != null && (days !== Math.trunc(days) || days < limits.normal_days_per_week_minimum || days > limits.normal_days_per_week_maximum)) return false;
return true;

// The extension inputs are checked against this version's declared bounds.
const facts = get(ctx.entry, 'employee_extension_data.term_facts', {});
const region = get(ctx.entry, 'terms.work_region', get(facts, 'work_region', get(facts, 'worksite_state', null)));
if (region != null && !ctx.lookup.work_regions.includes(region)) return false;
const carry = get(ctx.entry, 'terms.annual_leave_carry_limit_days', null);
if (carry != null && carry < ctx.lookup.annual_leave_carry_minimum) return false;
return true;

// PSMB Act 2001: a sealed compulsory registration records when its liability began.
if (get(ctx.entry, 'status', 'DRAFT') !== 'SEALED') return true;
const facts = get(ctx.entry, 'entity_extension_data', {});
if (get(facts, 'hrd_registration_class', null) !== ctx.lookup.compulsory_class) return true;
return typeof get(facts, 'hrd_registration_liability_on', null) === 'string' && get(facts, 'hrd_registration_liability_on', '') !== '';

// These cases must name the actual employment and carry their source document.
if (!ctx.lookup.kinds.includes(get(ctx.entry, 'kind', null))) return true;
return get(ctx.entry, 'employment_id', null) != null && get(ctx.entry, 'evidence_file', null) != null;

// EA s.25A(1): the employee's request is signed, on file, and not after the employer recorded it.
if (get(ctx.entry, 'kind', null) !== ctx.lookup.kind) return true;
const signed = get(ctx.entry, 'inputs.signed_on', null);
if (signed == null || get(ctx.entry, 'evidence_file', null) == null) return false;
return signed <= get(ctx.entry, 'opened_on', '9999-12-31');

// The departure case records the actual expected date and any later ordered return.
if (get(ctx.entry, 'kind', null) !== ctx.lookup.kind) return true;
const scheduled = get(ctx.entry, 'scheduled_on', null);
if (scheduled == null) return false;
const back = get(ctx.entry, 'inputs.expected_return_on', null);
return back == null || back >= scheduled;

// The employer's actual receipt cannot precede the recorded death.
if (get(ctx.entry, 'kind', null) !== ctx.lookup.kind) return true;
const death = get(ctx.entry, 'inputs.death_on', null);
if (death == null) return true;
return death <= get(ctx.entry, 'opened_on', '9999-12-31');
